   Linhas ..........: 1
   Escreve em tabela: nao
   Tabelas referidas: IV_QUESTAO
   Outras refs .....: IV_Q$AFERICAO_PECAS, IV_Q$AFERICAO_SERVICOS, IV_Q$AFERICAO_VENDA_MQ_IM
   Fonte: banco CRM (Vortice CRM / Tracbel) - extracao somente leitura
   ============================================================== */

CREATE VIEW IV$_PONTUACAO AS  SELECT XQ.TIPO, XQ.PROCESSO, SUM(PONTO)  AS PONTO  FROM (  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_UM WHEN 1 THEN 1 * QL.PESO ELSE 0 END AS PONTO FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_DOIS WHEN 1 THEN 2 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_TRES WHEN 1 THEN 3 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_QUATRO WHEN 1 THEN 4 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_CINCO WHEN 1 THEN 5 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_SEIS WHEN 1 THEN 6 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_SETE WHEN 1 THEN 7 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_OITO WHEN 1 THEN 8 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_NOVE WHEN 1 THEN 9 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q003_DEZ WHEN 1 THEN 10 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 3  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_1 WHEN 1 THEN 1 * QL.PESO ELSE 0 END AS PONTO FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_2 WHEN 1 THEN 2 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_3 WHEN 1 THEN 3 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_4 WHEN 1 THEN 4 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_5 WHEN 1 THEN 5 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_6 WHEN 1 THEN 6 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_7 WHEN 1 THEN 7 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_8 WHEN 1 THEN 8 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_9 WHEN 1 THEN 9 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'SERV' AS TIPO, QST.PROCESSO, CASE Q004_10 WHEN 1 THEN 10 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_SERVICOS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 4  UNION  SELECT 'PEÇA' AS TIPO, QST.PROCESSO, CASE Q001_UM WHEN 1 THEN 1 * QL.PESO ELSE 0 END AS PONTO FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA' AS TIPO, QST.PROCESSO, CASE Q001_DOIS WHEN 1 THEN 2 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_TRES WHEN 1 THEN 3 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_QUATRO WHEN 1 THEN 4 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_CINCO WHEN 1 THEN 5 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_SEIS WHEN 1 THEN 6 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_SETE WHEN 1 THEN 7 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_OITO WHEN 1 THEN 8 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_NOVE WHEN 1 THEN 9 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'PEÇA'  AS TIPO, QST.PROCESSO, CASE Q001_DEZ WHEN 1 THEN 10 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_PECAS QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND' AS TIPO, QST.PROCESSO, CASE Q001_UM WHEN 1 THEN 1 * QL.PESO ELSE 0 END AS PONTO FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND' AS TIPO, QST.PROCESSO, CASE Q001_DOIS WHEN 1 THEN 2 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_TRES WHEN 1 THEN 3 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_QUATRO WHEN 1 THEN 4 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_CINCO WHEN 1 THEN 5 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_SEIS WHEN 1 THEN 6 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_SETE WHEN 1 THEN 7 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_OITO WHEN 1 THEN 8 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_NOVE WHEN 1 THEN 9 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  UNION  SELECT 'VEND'  AS TIPO, QST.PROCESSO, CASE Q001_DEZ WHEN 1 THEN 10 * QL.PESO ELSE 0 END FROM IV_Q$AFERICAO_VENDA_MQ_IM QST INNER JOIN IV_QUESTAO QL ON QL.SEQFORMULARIO = QST.SEQFORMULARIO AND QL.QUESTAO = 1  ) XQ  GROUP BY XQ.TIPO, XQ.PROCESSO  